function countPeople(sheets: string[]): number {
  const people = sheets.flatMap((s) => (s === '' ? [] : s.split('\n'))).map((p) => p.split('\t'));
  const parent = people.map((_, i) => i);
  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
  const byName = new Map<string, number>();
  people.forEach((names, i) => {
    for (const n of names) {
      const at = byName.get(n);
      if (at === undefined) byName.set(n, i);
      else parent[root(at)] = root(i);
    }
  });
  return people.filter((_, i) => root(i) === i).length;
}

/** Works out one sheet's figures with the same hooks its header uses, and hands them up; shows nothing. */
function SheetFigures({ sheetId, onFigures }: { sheetId: string; onFigures: (id: string, f: Figures) => void }) {
  const people = usePeopleNames(sheetId).data ?? '';
  const due = [...useDueTotals(sheetId).values()].join(',');
  const overdue = [...useOverdue(sheetId).values()].map((f) => f.total).join(',');
  const dueTotals = useDueTotals(sheetId);
  const current = (usePeople(sheetId).data ?? []).filter((p) => !p.retiredFrom);
  const claims = useClaims(sheetId).data;
  // Joined into strings so the effect below only fires when a figure changes.
  const grades = GRADES.map((g) =>
    sumDues(current.filter((p) => p.grade === g).map((p) => dueTotals.get(p.id) ?? 'n/a'))).join(',');
  const statuses = STATUSES.map((s) => countWithStatus(claims, s)).join(',');
  useEffect(
    () => onFigures(sheetId, { people, due, overdue, grades, statuses }),
    [sheetId, people, due, overdue, grades, statuses, onFigures],
  );
  return null;
}

/** The consolidated figures over the sheet and all its descendants: the number of people (each counted once over
 *  the tree: people whose names or aliases match are one person), the due-total and overdue-total of every person
 *  of the tree added up, leaving out the single highest and the single lowest figure over the whole tree when three
 *  or more people have one, per grade the due-totals of the people on
 *  it added up, and per status the count of claims, all as of the screen's as-of date when one is
 *  set. A sheet with no children shows its own. */
function Consolidated({ sheetId }: { sheetId: string }) {
  const fig = useFigure();
  const descendants = useDescendants(sheetId);
  const [figures, setFigures] = useState<Record<string, Figures>>({});
  const [onFigures] = useState(() => (id: string, f: Figures) => setFigures((all) => ({ ...all, [id]: f })));
  const sheets = [sheetId, ...(descendants.data ?? [])];
  const shown = sheets.map((id) => figures[id]).filter((f): f is Figures => f !== undefined);
  const sum = (pick: (f: Figures) => string) => money(shown.reduce((s, f) => s + hundredths(pick(f)), 0n));
  const trimmed = (pick: (f: Figures) => string) =>
    trimmedSum(shown.flatMap((f) => (pick(f) === '' ? [] : pick(f).split(','))));
  const gradeDue = (i: number) => sum((f) => f.grades.split(',')[i]);
  const statusCount = (i: number) => shown.reduce((n, f) => n + Number(f.statuses.split(',')[i]), 0);
  return (
    <p data-testid="consolidated">
      {sheets.map((id) => (
        <SheetFigures key={id} sheetId={id} onFigures={onFigures} />
      ))}
      Consolidated: people <strong data-testid="consolidated-people-count">{countPeople(shown.map((f) => f.people))}</strong>
      {' '}· due total <strong data-testid="consolidated-due-total">{fig(trimmed((f) => f.due))}</strong>
      {' '}· overdue total <strong data-testid="consolidated-overdue-total">{fig(trimmed((f) => f.overdue))}</strong>
      {GRADES.map((g, i) => (
        <span key={g}>
          {' '}· grade {g} due total <strong data-testid={`consolidated-grade-${g}-due-total`}>{fig(gradeDue(i))}</strong>
        </span>
      ))}
      {STATUSES.map((s, i) => (
        <span key={s}>
          {' '}· {s} <strong data-testid={`consolidated-status-${s}-count`}>{statusCount(i)}</strong>
        </span>
      ))}
    </p>
  );
}

export const contribution = SheetBody.fill({ order: -9, Component: ({ sheetId }) => <Consolidated sheetId={sheetId} /> });
import { type ReactNode, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { GRADES, usePeople } from '../people/usePeople';
import { useDueTotals } from '../rates/useDueTotals';
import { sumDues } from '../rates/useRates';

/** Per grade, the due-totals of the people on it (retired left out) added up, as the sheet's summary shows them. */
function useGradeDueTotals(sheetId: string): Map<string, string> | undefined {
  const people = usePeople(sheetId);
  const dueTotals = useDueTotals(sheetId);
  if (people.data === undefined) return undefined;
  const current = people.data.filter((p) => !p.retiredFrom);
  return new Map(GRADES.map((g) => [g, sumDues(current.filter((p) => p.grade === g).map((p) => dueTotals.get(p.id) ?? 'n/a'))]));
}

/** Works out the other sheet's grade due-totals and shows them through `children` once they are read. */
function OtherFigures({ sheetId, children }: { sheetId: string; children: (totals: Map<string, string>) => ReactNode }) {
  const totals = useGradeDueTotals(sheetId);
  return totals === undefined ? null : children(totals);
}

/** Whether the sheet exists in the store, re-read from it; asking never makes it. */
function useSheetExists(sheetId: string, round: number) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'exists', round],
    queryFn: async () =>
      (await getJson<{ exists: boolean }>(`/api/sheets/${encodeURIComponent(sheetId)}/exists`)).exists,
    enabled: sheetId !== '',
  });
}

/** Compares this sheet with another: a sheet id entry and a button listing, per grade of this sheet,
 *  `<grade> <this sheet's summary due-total for it> <the other sheet's>` (0.00 for a grade the other sheet has no
 *  one on); a sheet that does not exist gives no lines. The other sheet is re-read from the store on each press. */
function SheetCompare({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const mine = useGradeDueTotals(sheetId);
  const [other, setOther] = useState('');
  // The other sheet being read (re-read from the store whenever `round` moves on), and whether to show it.
  const [reading, setReading] = useState<{ id: string; round: number }>({ id: '', round: 0 });
  const [shown, setShown] = useState(false);
  const exists = useSheetExists(reading.id, reading.round);

  const read = (id: string) => {
    if (id !== '' && id !== sheetId) queryClient.removeQueries({ queryKey: ['sheet', id] });
    setReading((r) => ({ id, round: r.round + 1 }));
  };

  return (
    <section>
      <input
        data-testid="compare-sheet"
        value={other}
        onChange={(e) => {
          setOther(e.target.value);
          setShown(false);
          read(e.target.value.trim());
        }}
      />{' '}
      <button
        type="button"
        data-testid="compare"
        onClick={() => {
          if (reading.id !== other.trim() || shown) read(other.trim());
          setShown(true);
        }}
      >
        Compare sheets
      </button>
      {reading.id !== '' && exists.data === true && mine !== undefined && (
        <OtherFigures key={`${reading.id}#${reading.round}`} sheetId={reading.id}>
          {(theirs) => (
            <ul>
              {shown &&
                GRADES.map((g) => (
                  <li key={g} data-testid="compare-line">
                    {[g, mine.get(g) ?? '0.00', theirs.get(g) ?? '0.00'].join(' ')}
                  </li>
                ))}
            </ul>
          )}
        </OtherFigures>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 44, Component: ({ sheetId }) => <SheetCompare sheetId={sheetId} /> });

